	private void insertMk_action( List<Mk_action> mk_actions )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = mk_actions.size();
		if ( mk_actionStmtSize != size ) {
			if ( mk_actionStmt != null ) {
				mk_actionStmt.close();
			}
			String values = "(?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			mk_actionStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO mk_action (id,campaign,media_type,start_date,end_date,survey)"  
				+" VALUES " + valuesList.toString()  );
			
			mk_actionStmtSize = size;
		}

		int offset = 1;
			
		for (Mk_action mk_action : mk_actions) {
			if ( mk_action.id == null )
				mk_actionStmt.setNull(offset++, 4);
			else
				mk_actionStmt.setInt(offset++, mk_action.id);
			if ( mk_action.campaign == null )
				mk_actionStmt.setNull(offset++, 4);
			else
				mk_actionStmt.setInt(offset++, mk_action.campaign);
			if ( mk_action.media_type == null )
				mk_actionStmt.setNull(offset++, 4);
			else
				mk_actionStmt.setInt(offset++, mk_action.media_type);
			if ( mk_action.start_date == null )
				mk_actionStmt.setNull(offset++, 93);
			else
				mk_actionStmt.setTimestamp(offset++, mk_action.start_date);
			if ( mk_action.end_date == null )
				mk_actionStmt.setNull(offset++, 93);
			else
				mk_actionStmt.setTimestamp(offset++, mk_action.end_date);
			if ( mk_action.survey == null )
				mk_actionStmt.setNull(offset++, 4);
			else
				mk_actionStmt.setInt(offset++, mk_action.survey);
		}
		mk_actionStmt.executeUpdate();
		mk_actionInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Mk_actions in {} milliseconds.", size, mk_actionInserted, elapsed );		
	}
		
