	private void insertAbsence( List<Absence> absences )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = absences.size();
		if ( absenceStmtSize != size ) {
			if ( absenceStmt != null ) {
				absenceStmt.close();
			}
			String values = "(?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			absenceStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO absence (id,course_alumn,absence_date,comments,evaluation)"  
				+" VALUES " + valuesList.toString()  );
			
			absenceStmtSize = size;
		}

		int offset = 1;
			
		for (Absence absence : absences) {
			if ( absence.id == null )
				absenceStmt.setNull(offset++, 4);
			else
				absenceStmt.setInt(offset++, absence.id);
			if ( absence.course_alumn == null )
				absenceStmt.setNull(offset++, 4);
			else
				absenceStmt.setInt(offset++, absence.course_alumn);
			if ( absence.absence_date == null )
				absenceStmt.setNull(offset++, 91);
			else
				absenceStmt.setDate(offset++, absence.absence_date);
			if ( absence.comments == null )
				absenceStmt.setNull(offset++, -1);
			else
				absenceStmt.setString(offset++, absence.comments);
			if ( absence.evaluation == null )
				absenceStmt.setNull(offset++, -6);
			else
				absenceStmt.setShort(offset++, absence.evaluation);
		}
		absenceStmt.executeUpdate();
		absenceInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Absences in {} milliseconds.", size, absenceInserted, elapsed );		
	}
		
