	private int personStmtSize = 0;

	private int personInserted = 0;

	private List<Person> persons = 
		new LinkedList<Person>();

	private PreparedStatement personStmt = null;

	private static class Person {
		private Integer registry; 
		private Date birth_date; 
		private Short gender; 
		private Short marital_status; 
		private String social_security_num; 
		private String name; 
		private String first_surname; 
		private String second_surname; 
	}
	
	private void insertPerson( List<Person> persons )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = persons.size();
		if ( personStmtSize != size ) {
			if ( personStmt != null ) {
				personStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			personStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO person (registry,birth_date,gender,marital_status,social_security_num,name,first_surname,second_surname)"  
				+" VALUES " + valuesList.toString()  );
			
			personStmtSize = size;
		}

		int offset = 1;
			
		for (Person person : persons) {
			if ( person.registry == null )
				personStmt.setNull(offset++, 4);
			else
				personStmt.setInt(offset++, person.registry);
			if ( person.birth_date == null )
				personStmt.setNull(offset++, 91);
			else
				personStmt.setDate(offset++, person.birth_date);
			if ( person.gender == null )
				personStmt.setNull(offset++, -6);
			else
				personStmt.setShort(offset++, person.gender);
			if ( person.marital_status == null )
				personStmt.setNull(offset++, -6);
			else
				personStmt.setShort(offset++, person.marital_status);
			if ( person.social_security_num == null )
				personStmt.setNull(offset++, 12);
			else
				personStmt.setString(offset++, person.social_security_num);
			if ( person.name == null )
				personStmt.setNull(offset++, 12);
			else
				personStmt.setString(offset++, person.name);
			if ( person.first_surname == null )
				personStmt.setNull(offset++, 12);
			else
				personStmt.setString(offset++, person.first_surname);
			if ( person.second_surname == null )
				personStmt.setNull(offset++, 12);
			else
				personStmt.setString(offset++, person.second_surname);
		}
		personStmt.executeUpdate();
		personInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Persons in {} milliseconds.", size, personInserted, elapsed );		
	}
		
	
	private void flushPerson(  )
	throws SQLException {
		if ( ! persons.isEmpty() )
			insertPerson(persons);
		if ( personStmt != null )
			personStmt.close();
	}	

	/**
	 * Person
	 * @param registry Registro de la Persona
	 * @param birth_date Fecha de nacimiento de la Persona
	 * @param gender Sexo de la Persona
	 * @param marital_status Estado civil de la Persona
	 * @param social_security_num Numero de Seguridad Social de la Persona
	 * @param name Nombre
	 * @param first_surname Primer Apellido 
	 * @param second_surname Segundo Apellido
	 * @throws SQLException
	*/
	protected void insertPerson(Integer registry, Date birth_date, Short gender, Short marital_status, String social_security_num, String name, String first_surname, String second_surname)
	throws SQLException {

		Person person_ = new Person();
		person_.registry = registry;
		person_.birth_date = birth_date;
		person_.gender = gender;
		person_.marital_status = marital_status;
		person_.social_security_num = social_security_num;
		person_.name = name;
		person_.first_surname = first_surname;
		person_.second_surname = second_surname;

		persons.add(person_);
		
		int personCount = persons.size();
		
		if ( 250 * personCount >=  this.maxAllowedPacket ){
			insertPerson(persons);
			persons.clear();
		} 
	}



