	private int account_entryStmtSize = 0;

	private int account_entryInserted = 0;

	private List<Account_entry> account_entrys = 
		new LinkedList<Account_entry>();

	private PreparedStatement account_entryStmt = null;

	private static class Account_entry {
		private Integer id; 
		private String account_period; 
		private Date entry_date; 
		private Short entry_type; 
		private Integer journal; 
		private Short security_level; 
		private String comments; 
	}
	
	private void insertAccount_entry( List<Account_entry> account_entrys )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = account_entrys.size();
		if ( account_entryStmtSize != size ) {
			if ( account_entryStmt != null ) {
				account_entryStmt.close();
			}
			String values = "(?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			account_entryStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO account_entry (id,account_period,entry_date,entry_type,journal,security_level,comments)"  
				+" VALUES " + valuesList.toString()  );
			
			account_entryStmtSize = size;
		}

		int offset = 1;
			
		for (Account_entry account_entry : account_entrys) {
			if ( account_entry.id == null )
				account_entryStmt.setNull(offset++, 4);
			else
				account_entryStmt.setInt(offset++, account_entry.id);
			if ( account_entry.account_period == null )
				account_entryStmt.setNull(offset++, 1);
			else
				account_entryStmt.setString(offset++, account_entry.account_period);
			if ( account_entry.entry_date == null )
				account_entryStmt.setNull(offset++, 91);
			else
				account_entryStmt.setDate(offset++, account_entry.entry_date);
			if ( account_entry.entry_type == null )
				account_entryStmt.setNull(offset++, -6);
			else
				account_entryStmt.setShort(offset++, account_entry.entry_type);
			if ( account_entry.journal == null )
				account_entryStmt.setNull(offset++, 4);
			else
				account_entryStmt.setInt(offset++, account_entry.journal);
			if ( account_entry.security_level == null )
				account_entryStmt.setNull(offset++, -6);
			else
				account_entryStmt.setShort(offset++, account_entry.security_level);
			if ( account_entry.comments == null )
				account_entryStmt.setNull(offset++, -1);
			else
				account_entryStmt.setString(offset++, account_entry.comments);
		}
		account_entryStmt.executeUpdate();
		account_entryInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Account_entrys in {} milliseconds.", size, account_entryInserted, elapsed );		
	}
		
		private int account_entryId = -1;
		
		private void initAccount_entryId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `account_entry`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.account_entryId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextAccount_entryId() {
			return ++this.account_entryId;
		} 

		public void setAccount_entryId(Integer account_entryId) {
			this.account_entryId = account_entryId;
		} 
	
	private void flushAccount_entry(  )
	throws SQLException {
		if ( ! account_entrys.isEmpty() )
			insertAccount_entry(account_entrys);
		if ( account_entryStmt != null )
			account_entryStmt.close();
	}	

