	private int sessionStmtSize = 0;

	private int sessionInserted = 0;

	private List<Session> sessions = 
		new LinkedList<Session>();

	private PreparedStatement sessionStmt = null;

	private static class Session {
		private Integer id; 
		private Timestamp endDate; 
		private String remote_address; 
		private String remote_host; 
		private String session_id; 
		private Timestamp startDate; 
		private Integer application_id; 
		private Integer user_id; 
	}
	
	private void insertSession( List<Session> sessions )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = sessions.size();
		if ( sessionStmtSize != size ) {
			if ( sessionStmt != null ) {
				sessionStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			sessionStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO session (id,endDate,remote_address,remote_host,session_id,startDate,application_id,user_id)"  
				+" VALUES " + valuesList.toString()  );
			
			sessionStmtSize = size;
		}

		int offset = 1;
			
		for (Session session : sessions) {
			if ( session.id == null )
				sessionStmt.setNull(offset++, 4);
			else
				sessionStmt.setInt(offset++, session.id);
			if ( session.endDate == null )
				sessionStmt.setNull(offset++, 93);
			else
				sessionStmt.setTimestamp(offset++, session.endDate);
			if ( session.remote_address == null )
				sessionStmt.setNull(offset++, 12);
			else
				sessionStmt.setString(offset++, session.remote_address);
			if ( session.remote_host == null )
				sessionStmt.setNull(offset++, 12);
			else
				sessionStmt.setString(offset++, session.remote_host);
			if ( session.session_id == null )
				sessionStmt.setNull(offset++, 12);
			else
				sessionStmt.setString(offset++, session.session_id);
			if ( session.startDate == null )
				sessionStmt.setNull(offset++, 93);
			else
				sessionStmt.setTimestamp(offset++, session.startDate);
			if ( session.application_id == null )
				sessionStmt.setNull(offset++, 4);
			else
				sessionStmt.setInt(offset++, session.application_id);
			if ( session.user_id == null )
				sessionStmt.setNull(offset++, 4);
			else
				sessionStmt.setInt(offset++, session.user_id);
		}
		sessionStmt.executeUpdate();
		sessionInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Sessions in {} milliseconds.", size, sessionInserted, elapsed );		
	}
		
