		private int deliveryId = -1;
		
		private void initDeliveryId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `delivery`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.deliveryId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextDeliveryId() {
			return ++this.deliveryId;
		} 

		public void setDeliveryId(Integer deliveryId) {
			this.deliveryId = deliveryId;
		} 
	
