	private int surveyStmtSize = 0;

	private int surveyInserted = 0;

	private List<Survey> surveys = 
		new LinkedList<Survey>();

	private PreparedStatement surveyStmt = null;

	private static class Survey {
		private Integer id; 
		private Boolean active; 
		private Timestamp creationDate; 
		private String description; 
	}
	
	private void insertSurvey( List<Survey> surveys )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = surveys.size();
		if ( surveyStmtSize != size ) {
			if ( surveyStmt != null ) {
				surveyStmt.close();
			}
			String values = "(?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			surveyStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO survey (id,active,creationDate,description)"  
				+" VALUES " + valuesList.toString()  );
			
			surveyStmtSize = size;
		}

		int offset = 1;
			
		for (Survey survey : surveys) {
			if ( survey.id == null )
				surveyStmt.setNull(offset++, 4);
			else
				surveyStmt.setInt(offset++, survey.id);
			if ( survey.active == null )
				surveyStmt.setNull(offset++, -7);
			else
				surveyStmt.setBoolean(offset++, survey.active);
			if ( survey.creationDate == null )
				surveyStmt.setNull(offset++, 93);
			else
				surveyStmt.setTimestamp(offset++, survey.creationDate);
			if ( survey.description == null )
				surveyStmt.setNull(offset++, 12);
			else
				surveyStmt.setString(offset++, survey.description);
		}
		surveyStmt.executeUpdate();
		surveyInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Surveys in {} milliseconds.", size, surveyInserted, elapsed );		
	}
		
