			if ( offer.version == null )
				offerStmt.setNull(offset++, 5);
			else
				offerStmt.setInt(offset++, offer.version);
			if ( offer.address == null )
				offerStmt.setNull(offset++, 4);
			else
				offerStmt.setInt(offset++, offer.address);
			if ( offer.tariff == null )
				offerStmt.setNull(offset++, 4);
			else
				offerStmt.setInt(offset++, offer.tariff);
			if ( offer.seller == null )
				offerStmt.setNull(offset++, 4);
