				offerStmt.setInt(offset++, offer.seller);
			if ( offer.supplier == null )
				offerStmt.setNull(offset++, 4);
			else
				offerStmt.setInt(offset++, offer.supplier);
			if ( offer.discount_expr == null )
				offerStmt.setNull(offset++, 12);
			else
				offerStmt.setString(offset++, offer.discount_expr);
			if ( offer.issue_date == null )
				offerStmt.setNull(offset++, 91);
